import { availableCopies } from "./store.mjs";

export function search(store, query = {}) {
  const { q, author, tag, yearFrom, yearTo, available, sort = "title" } = query;
  const page = query.page ?? 1;
  const pageSize = query.pageSize ?? 10;
  const words = q ? q.toLowerCase().split(/\s+/).filter(Boolean) : [];
  let items = store.books.filter((b) => {
    const hay = `${b.title} ${b.author}`.toLowerCase();
    if (!words.every((w) => hay.includes(w))) return false;
    if (author != null && b.author.toLowerCase() !== author.toLowerCase()) return false;
    if (tag != null && !b.tags.includes(tag)) return false;
    if (yearFrom != null && b.year < yearFrom) return false;
    if (yearTo != null && b.year > yearTo) return false;
    if (available === true && availableCopies(store, b.id) <= 0) return false;
    return true;
  });
  const byTitle = (a, b) => {
    const x = a.title.toLowerCase(), y = b.title.toLowerCase();
    return x < y ? -1 : x > y ? 1 : 0;
  };
  items = items.sort(sort === "year" ? (a, b) => b.year - a.year || byTitle(a, b) : byTitle);
  const total = items.length;
  return { items: items.slice((page - 1) * pageSize, page * pageSize), total, page, pages: Math.ceil(total / pageSize) };
}
