import { addBook } from "./store.mjs";

const esc = (v) => {
  const s = String(v);
  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};

export function exportBooks(store) {
  const lines = ["id,title,author,year,tags,copies"];
  for (const b of store.books) lines.push([b.id, b.title, b.author, b.year, b.tags.join(";"), b.copies].map(esc).join(","));
  return lines.join("\n") + "\n";
}

// Returns [{ line, fields }] where line is the 1-based starting line.
function parse(text) {
  const rows = [];
  let fields = [], f = "", q = false, line = 1, start = 1, any = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) {
      if (c === '"') {
        if (text[i + 1] === '"') { f += '"'; i++; } else q = false;
      } else { if (c === "\n") line++; f += c; }
    } else if (c === '"') { q = true; any = true; }
    else if (c === ",") { fields.push(f); f = ""; any = true; }
    else if (c === "\n" || c === "\r") {
      if (c === "\r" && text[i + 1] === "\n") i++;
      fields.push(f);
      if (any || fields.length > 1 || fields[0] !== "") rows.push({ line: start, fields });
      fields = []; f = ""; any = false; line++; start = line;
    } else { f += c; any = true; }
  }
  if (any || f !== "" || fields.length) { fields.push(f); rows.push({ line: start, fields }); }
  return rows;
}

const whole = (s) => /^-?\d+$/.test(s);

export function importBooks(store, text) {
  const rows = parse(text);
  const result = { added: 0, errors: [] };
  if (!rows.length) return result;
  const cols = rows[0].fields.map((c) => c.trim());
  for (const { line, fields } of rows.slice(1)) {
    const g = (n) => (fields[cols.indexOf(n)] ?? "").trim();
    const title = g("title"), author = g("author"), year = g("year"), copies = g("copies");
    let message = null;
    if (!title) message = "title is required";
    else if (!author) message = "author is required";
    else if (!whole(year)) message = "year must be a whole number";
    else if (copies !== "" && !(whole(copies) && Number(copies) > 0)) message = "copies must be a positive whole number";
    if (message) { result.errors.push({ line, message }); continue; }
    const tags = g("tags") ? g("tags").split(";") : [];
    addBook(store, { title, author, year: Number(year), tags, copies: copies === "" ? 1 : Number(copies) });
    result.added++;
  }
  return result;
}
