// CSV export/import of books.
import { addBook } from "./store.mjs";

const field = (v) => {
  const s = String(v ?? "");
  return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};

export function exportBooks(store) {
  const lines = ["id,title,author,year,tags,copies"];
  for (const b of store.books) {
    lines.push([b.id, b.title, b.author, b.year, (b.tags ?? []).join(";"), b.copies].map(field).join(","));
  }
  return lines.join("\n") + "\n";
}

// Returns [{ line, fields }] where line is the 1-based line a record starts on.
function parseRecords(text) {
  const records = [];
  let fields = [];
  let cur = "";
  let quoted = false;
  let line = 1;
  let start = 1;
  let pending = false;
  const endField = () => { fields.push(cur); cur = ""; };
  const endRecord = () => {
    endField();
    if (!(fields.length === 1 && fields[0] === "")) records.push({ line: start, fields });
    fields = [];
    pending = false;
  };
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quoted) {
      if (c === '"') {
        if (text[i + 1] === '"') { cur += '"'; i++; } else quoted = false;
      } else {
        if (c === "\n") line++;
        cur += c;
      }
    } else if (c === '"') {
      quoted = true;
      pending = true;
    } else if (c === ",") {
      endField();
      pending = true;
    } else if (c === "\n" || c === "\r") {
      if (c === "\r" && text[i + 1] === "\n") i++;
      endRecord();
      line++;
      start = line;
    } else {
      cur += c;
      pending = true;
    }
  }
  if (pending || cur !== "" || fields.length) endRecord();
  return records;
}

const WHOLE = /^-?\d+$/;

export function importBooks(store, text) {
  const records = parseRecords(String(text));
  const result = { added: 0, errors: [] };
  if (!records.length) return result;
  const header = records[0].fields.map((h) => h.trim());
  const idx = (name) => header.indexOf(name);
  const col = Object.fromEntries(["title", "author", "year", "tags", "copies"].map((n) => [n, idx(n)]));
  const get = (f, n) => (col[n] >= 0 ? (f[col[n]] ?? "") : "");

  for (const { line, fields } of records.slice(1)) {
    const title = get(fields, "title").trim();
    const author = get(fields, "author").trim();
    const yearS = get(fields, "year").trim();
    const copiesS = get(fields, "copies").trim();
    let message = null;
    if (!title) message = "title is required";
    else if (!author) message = "author is required";
    else if (!WHOLE.test(yearS)) message = "year must be a whole number";
    else if (copiesS !== "" && (!/^\d+$/.test(copiesS) || Number(copiesS) < 1)) message = "copies must be a positive whole number";
    if (message) {
      result.errors.push({ line, message });
      continue;
    }
    const tagsS = get(fields, "tags");
    const tags = tagsS.trim() === "" ? [] : tagsS.split(";").map((t) => t.trim()).filter(Boolean);
    addBook(store, { title, author, year: Number(yearS), tags, copies: copiesS === "" ? 1 : Number(copiesS) });
    result.added++;
  }
  return result;
}
